// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

library KaspaAddressLib {
    bytes6 private constant KASPA_PREFIX = "kaspa:";

    function verifyKaspaAddress(string memory addr) internal view returns (bool) {
        bytes memory addrBytes = bytes(addr);
        uint256 length = addrBytes.length;

        if (length <= KASPA_PREFIX.length || length > 67) {
            return false;
        }

        for (uint256 i = 0; i < KASPA_PREFIX.length; ++i) {
            if (addrBytes[i] != KASPA_PREFIX[i]) {
                return false;
            }
        }

        for (uint256 i = KASPA_PREFIX.length; i < length; ++i) {
            bytes1 char = addrBytes[i];
            if (
                char != "q" && char != "p" && char != "z" && char != "r" && char != "y" && char != "9" && char != "x"
                    && char != "8" && char != "g" && char != "f" && char != "2" && char != "t" && char != "v" && char != "d"
                    && char != "w" && char != "0" && char != "s" && char != "3" && char != "j" && char != "n" && char != "5"
                    && char != "4" && char != "k" && char != "h" && char != "c" && char != "e" && char != "6" && char != "m"
                    && char != "u" && char != "a" && char != "7" && char != "l"
            ) {
                return false;
            }
        }

        return true;
    }
}

