// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {IFeePolicy} from "./kasExitBridge/interfaces/IFeePolicy.sol";
import {IMailbox} from "./kasExitBridge/interfaces/IMailbox.sol";
import {KasExitBridgeBurnProxy} from "./kasExitBridge/KasExitBridgeBurnProxy.sol";
import {KaspaAddressLib} from "./kasExitBridge/libraries/KaspaAddressLib.sol";
import {KasExitBridgeMessageLib} from "./kasExitBridge/libraries/KasExitBridgeMessageLib.sol";
import {KasExitBridgeStorage} from "./kasExitBridge/libraries/KasExitBridgeStorage.sol";

import {Ownable2StepUpgradeable} from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

/// @notice Igra Exit bridge that burns iKAS, records canonical exit requests, and dispatches
/// Hyperlane messages for Kaspa-side unlocks.
/// @dev Intended for deployment behind a UUPS proxy and administration through Ownable2Step.
/// The owner controls throttle, fee, and endpoint configuration, while fee withdrawals are limited
/// to the owner or an explicitly configured fee claimer. The contract trusts the immutable
/// Hyperlane Mailbox passed to the implementation constructor and any configured fee policy to
/// behave according to their interfaces. Request records are stored in a fixed-size ring buffer,
/// and the Kaspa bridge endpoint falls back to a default constant until the owner overrides it.
contract KasExitBridge is Ownable2StepUpgradeable, ReentrancyGuardUpgradeable, UUPSUpgradeable {
    uint256 internal constant SOMPI_SCALE = 1e10;
    uint32 internal constant KASPA_DOMAIN = 1_262_570_320;
    bytes32 internal constant DEFAULT_KASPA_BRIDGE_ENDPOINT =
        0x12f926e6d45ae9ace4f1fae2b542f7391bb6af8a321ee48dc60aa57507a56cf3;
    uint256 private constant RING_BUFFER_SIZE = 8191;

    IMailbox internal immutable MAILBOX;

    event ExitRequested(uint32 requestId, bytes32 messageId, uint64 feeAmountSompi);
    event BurnIKas(uint256 amount);
    event ThrottleParamsUpdated(
        uint32 throttleWindowBlocks, uint32 throttleMaxExitsPerWindow, uint64 throttleMaxUnlockAmountPerWindow
    );
    event ExitAmountPolicyUpdated(uint64 minExitAmountSompi, uint64 maxExitAmountSompi);
    event FeePolicyUpdated(address feePolicyAddress);
    event FeeClaimerUpdated(address feeClaimer);
    event FeeClaimed(address to, uint256 amount);
    event KaspaBridgeEndpointUpdated(bytes32 kaspaBridgeEndpoint);

    error InvalidMailbox();
    error InvalidKasPayoutAddress();
    error InvalidExitAmount();
    error ExitAmountBelowMinimum(uint64 unlockAmountSompi, uint64 minExitAmountSompi);
    error ExitAmountAboveMaximum(uint64 unlockAmountSompi, uint64 maxExitAmountSompi);
    error InvalidThrottleWindowBlocks();
    error ThrottleExitCountExceeded(uint32 windowIndex, uint32 throttleMaxExitsPerWindow);
    error ThrottleUnlockAmountExceeded(
        uint32 windowIndex, uint64 attemptedUnlockAmountSompi, uint64 remainingUnlockAmountSompi
    );
    error InvalidMsgValue(uint256 expectedWei, uint256 actualWei);
    error ExitRequestCounterExhausted();
    error CurrentBlockNumberOverflow(uint256 blockNumber);
    error ThrottleWindowEndOverflow(uint32 windowIndex, uint32 throttleWindowBlocks);
    error UnauthorizedFeeWithdrawal(address caller);
    error FeeBalanceExceeded(uint256 claimedAmount, uint256 availableAmount);
    error RescueAmountExceedsBalance(uint256 requestedAmount, uint256 availableAmount);
    error InsufficientExcessBalance(uint256 minimumRequiredBalance, uint256 remainingBalance);
    error InvalidExitAmountPolicy(uint64 minExitAmountSompi, uint64 maxExitAmountSompi);
    error NativeTransferFailed();

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address mailbox_) {
        if (mailbox_ == address(0)) revert InvalidMailbox();
        MAILBOX = IMailbox(mailbox_);
        _disableInitializers();
    }

    /// @notice Initializes owner, throttle, and exit amount policy.
    /// @param initialOwner Initial contract owner.
    /// @param throttleWindowBlocks Number of blocks per throttle window.
    /// @param throttleMaxExitsPerWindow Max exits allowed per window.
    /// @param throttleMaxUnlockAmountPerWindow Max unlock amount per window in Sompi (0 = unbounded).
    /// @param minExitAmountSompi Minimum exit amount in Sompi (0 = disabled).
    /// @param maxExitAmountSompi Maximum exit amount in Sompi (0 = disabled).
    function initialize(
        address initialOwner,
        uint32 throttleWindowBlocks,
        uint32 throttleMaxExitsPerWindow,
        uint64 throttleMaxUnlockAmountPerWindow,
        uint64 minExitAmountSompi,
        uint64 maxExitAmountSompi
    ) external initializer {
        __Ownable_init(initialOwner);
        __Ownable2Step_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        _setThrottleParams(
            KasExitBridgeStorage.layout(),
            throttleWindowBlocks,
            throttleMaxExitsPerWindow,
            throttleMaxUnlockAmountPerWindow,
            true
        );
        _setExitAmountPolicy(KasExitBridgeStorage.layout(), minExitAmountSompi, maxExitAmountSompi, true);
    }

    /// @notice Returns current bridge configuration.
    /// @return kaspaBridgeEndpoint Effective Kaspa endpoint (default if not overridden).
    /// @return feePolicy Fee policy contract address.
    /// @return feeClaimer Authorized fee claimer address.
    /// @return throttleWindowBlocks Blocks per throttle window.
    /// @return throttleMaxExitsPerWindow Max exits per window.
    /// @return throttleMaxUnlockAmountPerWindowSompi Max unlock amount per window in Sompi.
    /// @return minExitSompi Minimum exit amount in Sompi.
    /// @return maxExitSompi Maximum exit amount in Sompi.
    function getConfig()
        external
        view
        returns (
            bytes32 kaspaBridgeEndpoint,
            address feePolicy,
            address feeClaimer,
            uint32 throttleWindowBlocks,
            uint32 throttleMaxExitsPerWindow,
            uint64 throttleMaxUnlockAmountPerWindowSompi,
            uint64 minExitSompi,
            uint64 maxExitSompi
        )
    {
        KasExitBridgeStorage.Layout storage l = KasExitBridgeStorage.layout();
        kaspaBridgeEndpoint = _effectiveKaspaBridgeEndpoint(l);
        feePolicy = l.feePolicyAddress;
        feeClaimer = l.feeClaimer;
        throttleWindowBlocks = l.throttleWindowBlocks;
        throttleMaxExitsPerWindow = l.throttleMaxExitsPerWindow;
        throttleMaxUnlockAmountPerWindowSompi = l.throttleMaxUnlockAmountPerWindow;
        minExitSompi = l.minExitAmountSompi;
        maxExitSompi = l.maxExitAmountSompi;
    }

    /// @notice Returns the next exit request id to be assigned.
    function nextExitRequestId() external view returns (uint32) {
        return KasExitBridgeStorage.layout().exitRequestCounter;
    }

    /// @notice Quotes fee for an exit request.
    /// @param originBurner Request sender address.
    /// @param unlockAmountSompi Requested unlock amount in Sompi.
    /// @return feeAmountSompi Fee amount in Sompi.
    function quoteFee(address originBurner, uint64 unlockAmountSompi) external view returns (uint64 feeAmountSompi) {
        return _quoteFee(KasExitBridgeStorage.layout().feePolicyAddress, originBurner, unlockAmountSompi);
    }

    /// @notice Returns a recorded exit request if still present in ring buffer.
    /// @param requestId Exit request id.
    /// @return exists True if record exists and was not overwritten.
    function getExitRequest(uint32 requestId)
        external
        view
        returns (
            bool exists,
            uint32 recordedAtBlock,
            uint64 feeAmountSompi,
            uint64 unlockAmountSompi,
            bytes32 messageId
        )
    {
        KasExitBridgeStorage.ExitRequestRecord storage record =
            KasExitBridgeStorage.layout().records[requestId % RING_BUFFER_SIZE];
        if (record.messageId == bytes32(0) || record.requestId != requestId) {
            return (false, 0, 0, 0, bytes32(0));
        }

        return (true, record.recordedAtBlock, record.feeAmountSompi, record.unlockAmountSompi, record.messageId);
    }

    /// @notice Returns current throttle window status and remaining capacity.
    function throttleStatus()
        external
        view
        returns (uint32 windowIndex, uint32 windowEndsAtBlock, uint32 remainingExits, uint64 remainingUnlockAmountSompi)
    {
        KasExitBridgeStorage.Layout storage l = KasExitBridgeStorage.layout();
        uint32 currentBlock = _currentBlockNumber();
        uint32 throttleWindowBlocks = l.throttleWindowBlocks;
        windowIndex = currentBlock / throttleWindowBlocks;

        uint256 windowEndsAtBlock256 = (uint256(windowIndex) + 1) * uint256(throttleWindowBlocks) - 1;
        if (windowEndsAtBlock256 > type(uint32).max) {
            revert ThrottleWindowEndOverflow(windowIndex, throttleWindowBlocks);
        }
        windowEndsAtBlock = uint32(windowEndsAtBlock256);

        uint32 usedExits = windowIndex == l.currentWindowIndex ? l.exitsUsedInCurrentWindow : 0;
        uint64 usedUnlockAmountSompi = windowIndex == l.currentWindowIndex ? l.unlockAmountUsedInCurrentWindow : 0;
        uint32 throttleMaxExitsPerWindow = l.throttleMaxExitsPerWindow;

        if (throttleMaxExitsPerWindow == 0 || usedExits >= throttleMaxExitsPerWindow) {
            remainingExits = 0;
        } else {
            remainingExits = throttleMaxExitsPerWindow - usedExits;
        }

        uint64 throttleMaxUnlockAmountPerWindow = l.throttleMaxUnlockAmountPerWindow;
        if (throttleMaxUnlockAmountPerWindow == 0) {
            remainingUnlockAmountSompi = type(uint64).max;
        } else if (usedUnlockAmountSompi >= throttleMaxUnlockAmountPerWindow) {
            remainingUnlockAmountSompi = 0;
        } else {
            remainingUnlockAmountSompi = throttleMaxUnlockAmountPerWindow - usedUnlockAmountSompi;
        }
    }

    /// @notice Returns total burned iKAS in wei units.
    function totalBurned() external view returns (uint256) {
        return uint256(KasExitBridgeStorage.layout().totalBurnedSompi) * SOMPI_SCALE;
    }

    /// @notice Returns total charged fees in wei units.
    function totalFeeCharged() external view returns (uint256) {
        return uint256(KasExitBridgeStorage.layout().chargedFeeSompi) * SOMPI_SCALE;
    }

    /// @notice Requests an exit by burning iKAS and dispatching a message.
    /// @dev Burned/charged Sompi totals use `uint64` by design as a protocol-lifetime bound;
    /// this cap is not expected to be reachable due to constrained supply.
    /// @param kasPayoutAddress Kaspa payout address.
    /// @param unlockAmountSompi Unlock amount in Sompi.
    /// @return requestId Assigned request id.
    /// @return messageId Hyperlane message id.
    function requestExit(string calldata kasPayoutAddress, uint64 unlockAmountSompi)
        external
        payable
        nonReentrant
        returns (uint32 requestId, bytes32 messageId)
    {
        if (!KaspaAddressLib.verifyKaspaAddress(kasPayoutAddress)) revert InvalidKasPayoutAddress();
        if (unlockAmountSompi == 0) revert InvalidExitAmount();

        KasExitBridgeStorage.Layout storage l = KasExitBridgeStorage.layout();
        uint32 currentBlock = _currentBlockNumber();
        _syncThrottleWindow(l, currentBlock);

        uint64 minExitAmountSompi = l.minExitAmountSompi;
        uint64 maxExitAmountSompi = l.maxExitAmountSompi;
        if (minExitAmountSompi != 0 && unlockAmountSompi < minExitAmountSompi) {
            revert ExitAmountBelowMinimum(unlockAmountSompi, minExitAmountSompi);
        }
        if (maxExitAmountSompi != 0 && unlockAmountSompi > maxExitAmountSompi) {
            revert ExitAmountAboveMaximum(unlockAmountSompi, maxExitAmountSompi);
        }

        uint32 throttleMaxExitsPerWindow = l.throttleMaxExitsPerWindow;
        if (l.exitsUsedInCurrentWindow >= throttleMaxExitsPerWindow) {
            revert ThrottleExitCountExceeded(l.currentWindowIndex, throttleMaxExitsPerWindow);
        }

        uint64 throttleMaxUnlockAmountPerWindow = l.throttleMaxUnlockAmountPerWindow;
        if (throttleMaxUnlockAmountPerWindow != 0) {
            uint64 usedUnlockAmountSompi = l.unlockAmountUsedInCurrentWindow;
            uint64 remainingUnlockAmountSompi = throttleMaxUnlockAmountPerWindow - usedUnlockAmountSompi;
            if (unlockAmountSompi > remainingUnlockAmountSompi) {
                revert ThrottleUnlockAmountExceeded(l.currentWindowIndex, unlockAmountSompi, remainingUnlockAmountSompi);
            }
        }

        uint64 feeAmountSompi = _quoteFee(l.feePolicyAddress, msg.sender, unlockAmountSompi);
        uint256 expectedMsgValueWei = (uint256(unlockAmountSompi) + uint256(feeAmountSompi)) * SOMPI_SCALE;
        if (msg.value != expectedMsgValueWei) {
            revert InvalidMsgValue(expectedMsgValueWei, msg.value);
        }

        requestId = l.exitRequestCounter;
        if (requestId == type(uint32).max) revert ExitRequestCounterExhausted();

        uint256 burnAmountWei = uint256(unlockAmountSompi) * SOMPI_SCALE;
        new KasExitBridgeBurnProxy{value: burnAmountWei}();
        // Sompi totals are bounded by practical supply constraints and cannot exceed uint64 max.
        l.totalBurnedSompi += unlockAmountSompi;
        emit BurnIKas(burnAmountWei);

        bytes memory body =
            KasExitBridgeMessageLib.encodeBodyV1(requestId, unlockAmountSompi, msg.sender, kasPayoutAddress);
        messageId = MAILBOX.dispatch(KASPA_DOMAIN, _effectiveKaspaBridgeEndpoint(l), body);

        KasExitBridgeStorage.ExitRequestRecord storage record = l.records[requestId % RING_BUFFER_SIZE];
        record.requestId = requestId;
        record.recordedAtBlock = currentBlock;
        record.feeAmountSompi = feeAmountSompi;
        record.unlockAmountSompi = unlockAmountSompi;
        record.messageId = messageId;

        unchecked {
            l.exitRequestCounter = requestId + 1;
            l.exitsUsedInCurrentWindow += 1;
        }

        if (throttleMaxUnlockAmountPerWindow != 0) {
            l.unlockAmountUsedInCurrentWindow += unlockAmountSompi;
        }
        // Fee amounts are accounted in Sompi and cannot exceed uint64 max.
        l.chargedFeeSompi += feeAmountSompi;

        emit ExitRequested(requestId, messageId, feeAmountSompi);
    }

    /// @notice Updates throttle parameters.
    function setThrottleParams(
        uint32 throttleWindowBlocks,
        uint32 throttleMaxExitsPerWindow,
        uint64 throttleMaxUnlockAmountPerWindow
    ) external onlyOwner {
        _setThrottleParams(
            KasExitBridgeStorage.layout(),
            throttleWindowBlocks,
            throttleMaxExitsPerWindow,
            throttleMaxUnlockAmountPerWindow,
            true
        );
    }

    /// @notice Updates min/max exit amount policy.
    function setExitAmountPolicy(uint64 minExitAmountSompi, uint64 maxExitAmountSompi) external onlyOwner {
        _setExitAmountPolicy(KasExitBridgeStorage.layout(), minExitAmountSompi, maxExitAmountSompi, true);
    }

    /// @notice Sets fee policy contract.
    function setFeePolicy(address feePolicyAddress) external onlyOwner {
        KasExitBridgeStorage.layout().feePolicyAddress = feePolicyAddress;
        emit FeePolicyUpdated(feePolicyAddress);
    }

    /// @notice Sets authorized fee claimer.
    function setFeeClaimer(address feeClaimer) external onlyOwner {
        KasExitBridgeStorage.layout().feeClaimer = feeClaimer;
        emit FeeClaimerUpdated(feeClaimer);
    }

    /// @notice Sets Kaspa bridge endpoint (zero resets to default endpoint).
    function setKaspaBridgeEndpoint(bytes32 kaspaBridgeEndpoint) external onlyOwner {
        KasExitBridgeStorage.layout().kaspaBridgeEndpoint = kaspaBridgeEndpoint;
        emit KaspaBridgeEndpointUpdated(kaspaBridgeEndpoint);
    }

    /// @notice Claims charged fees.
    /// @dev If `amountSompi` is zero, claims the maximum currently available whole Sompi.
    /// @param to Recipient address.
    /// @param amountSompi Amount to claim in Sompi (0 = max available).
    function claimFees(address to, uint64 amountSompi) external nonReentrant {
        KasExitBridgeStorage.Layout storage l = KasExitBridgeStorage.layout();
        address caller = msg.sender;
        if (caller != owner() && (caller != l.feeClaimer || l.feeClaimer == address(0))) {
            revert UnauthorizedFeeWithdrawal(caller);
        }

        uint256 availableFeesWei = _availableFeesWei(l);
        uint64 availableFeesSompi = uint64(availableFeesWei / SOMPI_SCALE);
        uint64 claimAmountSompi = amountSompi == 0 ? availableFeesSompi : amountSompi;
        uint256 claimAmountWei = uint256(claimAmountSompi) * SOMPI_SCALE;
        if (claimAmountWei > availableFeesWei) {
            revert FeeBalanceExceeded(claimAmountWei, availableFeesWei);
        }

        l.claimedFeeSompi += claimAmountSompi;

        emit FeeClaimed(to, claimAmountWei);

        (bool success,) = to.call{value: claimAmountWei}("");
        if (!success) revert NativeTransferFailed();
    }

    /// @notice Rescues excess iKAS sent directly to this contract.
    /// @dev Enforces a minimum remaining balance based on fee accounting.
    /// @param to Recipient address.
    /// @param amountWei Amount to rescue in wei.
    function rescueExcessIKas(address to, uint256 amountWei) external onlyOwner nonReentrant {
        KasExitBridgeStorage.Layout storage l = KasExitBridgeStorage.layout();
        uint256 balanceWei = address(this).balance;
        if (amountWei > balanceWei) {
            revert RescueAmountExceedsBalance(amountWei, balanceWei);
        }

        uint256 minimumRequiredBalanceWei = 0;
        if (l.chargedFeeSompi > l.claimedFeeSompi) {
            minimumRequiredBalanceWei = uint256(l.chargedFeeSompi - l.claimedFeeSompi) * SOMPI_SCALE;
        }

        uint256 remainingBalanceWei = balanceWei - amountWei;
        if (remainingBalanceWei < minimumRequiredBalanceWei) {
            revert InsufficientExcessBalance(minimumRequiredBalanceWei, remainingBalanceWei);
        }

        (bool success,) = to.call{value: amountWei}("");
        if (!success) revert NativeTransferFailed();
    }

    function _availableFeesWei(KasExitBridgeStorage.Layout storage l) private view returns (uint256 availableFeesWei) {
        uint256 chargedFeeWei = uint256(l.chargedFeeSompi) * SOMPI_SCALE;
        uint256 claimedFeeWei = uint256(l.claimedFeeSompi) * SOMPI_SCALE;
        uint256 unclaimedFeeWei = claimedFeeWei >= chargedFeeWei ? 0 : chargedFeeWei - claimedFeeWei;
        uint256 balanceWei = address(this).balance;
        return balanceWei < unclaimedFeeWei ? balanceWei : unclaimedFeeWei;
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    function _setThrottleParams(
        KasExitBridgeStorage.Layout storage l,
        uint32 throttleWindowBlocks,
        uint32 throttleMaxExitsPerWindow,
        uint64 throttleMaxUnlockAmountPerWindow,
        bool shouldEmit
    ) private {
        if (throttleWindowBlocks == 0) revert InvalidThrottleWindowBlocks();

        uint32 currentBlock = _currentBlockNumber();
        l.throttleWindowBlocks = throttleWindowBlocks;
        l.throttleMaxExitsPerWindow = throttleMaxExitsPerWindow;
        l.throttleMaxUnlockAmountPerWindow = throttleMaxUnlockAmountPerWindow;
        l.currentWindowIndex = currentBlock / throttleWindowBlocks;
        l.exitsUsedInCurrentWindow = 0;
        l.unlockAmountUsedInCurrentWindow = 0;

        if (shouldEmit) {
            emit ThrottleParamsUpdated(
                throttleWindowBlocks, throttleMaxExitsPerWindow, throttleMaxUnlockAmountPerWindow
            );
        }
    }

    function _setExitAmountPolicy(
        KasExitBridgeStorage.Layout storage l,
        uint64 minExitAmountSompi,
        uint64 maxExitAmountSompi,
        bool shouldEmit
    ) private {
        if (minExitAmountSompi != 0 && maxExitAmountSompi != 0 && minExitAmountSompi > maxExitAmountSompi) {
            revert InvalidExitAmountPolicy(minExitAmountSompi, maxExitAmountSompi);
        }

        l.minExitAmountSompi = minExitAmountSompi;
        l.maxExitAmountSompi = maxExitAmountSompi;

        if (shouldEmit) {
            emit ExitAmountPolicyUpdated(minExitAmountSompi, maxExitAmountSompi);
        }
    }

    function _syncThrottleWindow(KasExitBridgeStorage.Layout storage l, uint32 currentBlock) private {
        uint32 throttleWindowBlocks = l.throttleWindowBlocks;
        if (throttleWindowBlocks == 0) revert InvalidThrottleWindowBlocks();

        uint32 liveWindowIndex = currentBlock / throttleWindowBlocks;
        if (liveWindowIndex != l.currentWindowIndex) {
            l.currentWindowIndex = liveWindowIndex;
            l.exitsUsedInCurrentWindow = 0;
            l.unlockAmountUsedInCurrentWindow = 0;
        }
    }

    function _effectiveKaspaBridgeEndpoint(KasExitBridgeStorage.Layout storage l) private view returns (bytes32) {
        bytes32 kaspaBridgeEndpoint = l.kaspaBridgeEndpoint;
        if (kaspaBridgeEndpoint == bytes32(0)) {
            return DEFAULT_KASPA_BRIDGE_ENDPOINT;
        }

        return kaspaBridgeEndpoint;
    }

    function _quoteFee(address feePolicyAddress, address originBurner, uint64 unlockAmountSompi)
        private
        view
        returns (uint64 feeAmountSompi)
    {
        if (feePolicyAddress == address(0)) {
            return 0;
        }

        return IFeePolicy(feePolicyAddress).computeFee(originBurner, unlockAmountSompi);
    }

    function _currentBlockNumber() private view returns (uint32 currentBlock) {
        uint256 blockNumber = block.number;
        if (blockNumber > type(uint32).max) revert CurrentBlockNumberOverflow(blockNumber);
        return uint32(blockNumber);
    }
}
